from __future__ import annotations

import json
from pathlib import Path
import sqlite3
import subprocess

ROOT = Path.home() / ".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
TASK_ID = "A2Z-V4-SOL-PROPOSAL-20261006-R2"
UNIT = "prediction-a2z-v4-model@A2Z-V4-SOL-PROPOSAL-20261006-R2.service"
REQUEST = ROOT / "requests" / f"{TASK_ID}.json"
RESULT = ROOT / "model_results" / f"{TASK_ID}.json"
MODELS = ROOT / "models"
DB = MODELS / "runtime.sqlite"

def systemd_snapshot():
    cp = subprocess.run(
        ["systemctl", "--user", "show", UNIT],
        text=True, capture_output=True, timeout=20, check=False,
    )
    wanted = {
        "ActiveState", "SubState", "Result", "ExecMainStatus", "ExecMainCode",
        "ExecMainStartTimestamp", "ExecMainExitTimestamp"
    }
    out = {"rc": cp.returncode}
    for line in cp.stdout.splitlines():
        if "=" not in line:
            continue
        k, v = line.split("=", 1)
        if k in wanted:
            out[k] = v
    return out

def journal_snapshot():
    cp = subprocess.run(
        ["journalctl", "--user", "-u", UNIT, "-n", "120", "--no-pager"],
        text=True, capture_output=True, timeout=20, check=False,
    )
    keys = ("error", "fail", "usage", "quota", "blocked", "traceback", "model", TASK_ID.lower())
    selected = []
    for line in cp.stdout.splitlines():
        low = line.lower()
        if any(k in low for k in keys):
            selected.append(line[-600:])
    return {"rc": cp.returncode, "tail": selected[-12:]}

diag = {
    "task_id": TASK_ID,
    "request_exists": REQUEST.is_file() and not REQUEST.is_symlink(),
    "result_exists": RESULT.is_file() and not RESULT.is_symlink(),
    "db_exists": DB.is_file() and not DB.is_symlink(),
    "systemd": systemd_snapshot(),
    "journal": journal_snapshot(),
}

if diag["result_exists"]:
    try:
        obj = json.loads(RESULT.read_text(encoding="utf-8"))
    except Exception as exc:
        print("SOL_R2_RUNTIME_DIAG=" + json.dumps({**diag, "classification": "RESULT_PRESENT_INVALID_JSON", "error": type(exc).__name__}, sort_keys=True))
        raise SystemExit(10)
    diag["result_model"] = obj.get("model")
    diag["result_policy"] = obj.get("model_policy")
    diag["result_phase"] = obj.get("phase")
    diag["classification"] = "RESULT_NOW_PRESENT"
    print("SOL_R2_RUNTIME_DIAG=" + json.dumps(diag, sort_keys=True))
    print("SOL_R2_RESULT_NOW_PRESENT=1")
    raise SystemExit(0)

if not diag["request_exists"]:
    diag["classification"] = "REQUEST_MISSING"
elif not diag["db_exists"]:
    diag["classification"] = "MODEL_RUNTIME_DB_MISSING"
else:
    db = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
    try:
        row = db.execute(
            "select status,attempt,thread,run,body from tasks where id=?",
            (TASK_ID,),
        ).fetchone()
        trans = db.execute(
            "select state,reason,attempt,checkpoint,next_action,stamp,retry "
            "from transitions where task=? order by seq desc limit 6",
            (TASK_ID,),
        ).fetchall()
    finally:
        db.close()

    diag["transitions"] = [
        {
            "state": x[0], "reason": x[1], "attempt": x[2],
            "checkpoint": x[3], "next_action": x[4],
            "stamp": x[5], "retry": x[6],
        }
        for x in trans
    ]

    if row is None:
        diag["classification"] = "TASK_NOT_ENQUEUED"
    else:
        status, attempt, thread, run, body = row
        diag["runtime_task"] = {
            "status": status, "attempt": attempt, "thread_present": bool(thread), "run": run
        }
        try:
            body_obj = json.loads(body)
            diag["runtime_task"]["model_policy"] = body_obj.get("model_policy")
            diag["runtime_task"]["phase"] = body_obj.get("phase")
            diag["runtime_task"]["route_task_id"] = body_obj.get("route_task_id")
        except Exception:
            diag["runtime_task"]["body_parse"] = "INVALID"

        if run:
            run_dir = MODELS / run
            diag["run_dir_exists"] = run_dir.is_dir()
            for name in ("WORKER.json", "COMPLETE.json", "worker_error.json", "events.jsonl", "stderr.log"):
                p = run_dir / name
                diag[name + "_exists"] = p.is_file()
            err = run_dir / "worker_error.json"
            if err.is_file():
                try:
                    diag["worker_error"] = json.loads(err.read_text(encoding="utf-8"))
                except Exception:
                    diag["worker_error"] = err.read_text(errors="replace")[-800:]
            stderr = run_dir / "stderr.log"
            if stderr.is_file():
                txt = stderr.read_text(errors="replace")
                diag["stderr_tail"] = txt[-1200:]
            events = run_dir / "events.jsonl"
            if events.is_file():
                lines = events.read_text(errors="replace").splitlines()
                diag["events_tail"] = lines[-8:]

        if status == "PAUSED_USAGE_LIMIT":
            diag["classification"] = "PAUSED_USAGE_LIMIT"
        elif status == "WAITING_RETRY":
            diag["classification"] = "WAITING_RETRY"
        elif status == "RUNNING":
            diag["classification"] = "RUNNING_WITHOUT_RESULT"
        elif status == "COMPLETE":
            diag["classification"] = "COMPLETE_WITHOUT_RESULT"
        elif status == "FAILED":
            diag["classification"] = "MODEL_TASK_FAILED"
        elif status == "QUEUED":
            diag["classification"] = "QUEUED_NOT_COMPLETED"
        else:
            diag["classification"] = "UNEXPECTED_RUNTIME_STATUS"

print("SOL_R2_RUNTIME_DIAG=" + json.dumps(diag, sort_keys=True, ensure_ascii=False))
print("NO_ASTRA_BUILD_TEST_OR_MEASUREMENT=1")
raise SystemExit(10)
